/**
 * @name Subprocess Argument Taint
 * @description Tracks taint from function parameters to subprocess calls in rebuild.py
 * @kind path-problem
 * @problem.severity error
 * @id py/subprocess-taint-rebuild
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SubprocessTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module SubprocessTaintFlow = TaintTracking::Global<SubprocessTaintConfig>;
import SubprocessTaintFlow::PathGraph

from SubprocessTaintFlow::PathNode source, SubprocessTaintFlow::PathNode sink
where SubprocessTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Subprocess argument derived from parameter $@.", source.getNode(), "parameter"

/**
 * @name Path traversal in file operations
 * @description Opening files with paths derived from untrusted input can lead to path traversal.
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 *       external/cwe/cwe-023
 *       external/cwe/cwe-073
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider all function parameters as potential sources for a library
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "parameter"
